using namespace std;

const long long INF = (1LL<<60);

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int T;
    if(!(cin>>T)) return 0;
    while(T--){
        int N, M;
        cin>>N>>M;
        vector<vector<Edge>> adj(N);
        for(int i=0;i<M;i++){
            int X,Y,D;
            cin>>X>>Y>>D;
            adj[X].push_back({Y,(int)D});
            adj[Y].push_back({X,(int)D});
        }
        int S;
        cin>>S;
        vector<int> store_nodes(S);
        for(int i=0;i<S;i++){
            cin>>store_nodes[i];
        }

        // vertices: house (0) + store nodes
        vector<int> vertices;
        vertices.reserve(1+S);
        vertices.push_back(0);
        for(int node: store_nodes){
            vertices.push_back(node);
        }
        int Vsize = vertices.size(); // should be 1+S

        // distance matrix between vertices
        vector<vector<long long>> distV(Vsize, vector<long long>(Vsize, INF));

        // For each vertex in vertices, run Dijkstra on whole graph
        for(int idx=0; idx<Vsize; ++idx){
            int src = vertices[idx];
            vector<long long> distGraph(N, INF);
            priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
            distGraph[src] = 0;
            pq.emplace(0LL, src);
            while(!pq.empty()){
                auto top = pq.top(); pq.pop();
                long long d = top.first;
                int v = top.second;
                if(d != distGraph[v]) continue;
                for(const Edge& e : adj[v]){
                    long long nd = d + e.w;
                    if(nd < distGraph[e.to]){
                        distGraph[e.to] = nd;
                        pq.emplace(nd, e.to);
                    }
                }
            }
            // fill row
            for(int j=0; j<Vsize; ++j){
                int dst = vertices[j];
                distV[idx][j] = distGraph[dst];
            }
        }

        // Now find minimal tour starting at vertex 0 (index 0) and visiting all other vertices (stores)
        // Permutations of indices 1..Vsize-1 (these correspond to store nodes)
        vector<int> permStores;
        for(int i=1; i<Vsize; ++i){
            permStores.push_back(i);
        }
        sort(permStores.begin(), permStores.end());
        long long best = INF;
        do{
            long long total = distV[0][permStores[0]];
            for(size_t k=0; k+1<permStores.size(); ++k){
                total += distV[permStores[k]][permStores[k+1]];
            }
            total += distV[permStores.back()][0];
            if(total < best) best = total;
        } while(next_permutation(permStores.begin(), permStores.end()));

        cout<<best<<"\n";
    }
    return 0;
}
